#!/bin/bash
# devshop-commit-guard.sh — commit-time guard for devshop hygiene.
# Called from .hooks/pre-commit (generated by init-devshop.sh, invoked by husky).
# git -c bypass flags work natively in husky context (inherited by child processes).
#
# Five checks (all blocking via exit 1). Each check has a name; the runner
# executes them in the order listed below:
#
#   mixed-commit       (DETERMINISTIC, project repo only)
#                      devshop + project files staged together → block
#   docs-drift         (SEMANTIC)
#                      tooling changed → reviews ALL docs (including ones that don't
#                      yet mention the change — new features need first-time docs)
#   doc-consistency    (SEMANTIC)
#                      reference doc changed → requires review explanation
#   cross-repo         (DETERMINISTIC)
#                      other repo has uncommitted changes → block
#   release-coverage   (SEMANTIC, devshop repo only)
#                      kit/version staged → adversarial review of whether changes
#                      since last tag have adequate test coverage
#
# Semantic checks always run an adversarial review (adversarial-review.sh) —
# either of a review reason provided via git -c flag, or (for release-coverage)
# of the actual coverage directly. Deterministic checks auto-pass when the
# condition is met.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"

# --- Repo detection ---
GIT_ROOT=$(git rev-parse --show-toplevel 2>/dev/null || echo "")
# Detect devshop-self mode: workspace IS the devshop repo (opened directly in VS Code).
# kit/ is a real directory in the devshop repo but .devshopkit/ is always a symlink in projects.
if [ "$GIT_ROOT" != "/devshop" ] && [ -d "$GIT_ROOT/kit" ] && [ ! -L "$GIT_ROOT/kit" ]; then
  # Devshop-self mode: devshop opened directly as workspace (no project repo)
  CURRENT_REPO=devshop; OTHER_REPO=""; OTHER_NAME=""
else
  case "$GIT_ROOT" in
    /workspace) CURRENT_REPO=project; OTHER_REPO=/devshop;  OTHER_NAME="devshop (abra-kadabra)" ;;
    /devshop)   CURRENT_REPO=devshop; OTHER_REPO=/workspace; OTHER_NAME="project" ;;
    *)          CURRENT_REPO=unknown; OTHER_REPO="";          OTHER_NAME="" ;;
  esac
fi

STAGED=$(git diff --cached --name-only)
[ -z "$STAGED" ] && exit 0

FAILED=false

# --- Classify staged files ---
DEVSHOP_PATTERNS=(
  '^\.devshopkit/'
  '^\.claude/'
  '^\.dcg\.toml$'
)
DEVSHOP_REGEX=$(IFS='|'; echo "${DEVSHOP_PATTERNS[*]}")

DEVSHOP_FILES=()
PROJECT_FILES=()

while IFS= read -r file; do
  [ -z "$file" ] && continue
  if echo "$file" | grep -qE "$DEVSHOP_REGEX"; then
    DEVSHOP_FILES+=("$file")
  else
    PROJECT_FILES+=("$file")
  fi
done <<< "$STAGED"

# --- mixed-commit (DETERMINISTIC, project repo only) ---
if [ "$CURRENT_REPO" = "project" ]; then
  if [ ${#DEVSHOP_FILES[@]} -gt 0 ] && [ ${#PROJECT_FILES[@]} -gt 0 ]; then
    echo ""
    echo "✖ Mixed commit: devshop + project files staged together."
    echo "  Devshop changes should be in separate commits."
    echo ""
    echo "  Devshop files:"
    for f in "${DEVSHOP_FILES[@]}"; do echo "    $f"; done
    echo "  Project files:"
    for f in "${PROJECT_FILES[@]}"; do echo "    $f"; done
    echo ""
    echo "  Unstage one set and commit separately."
    FAILED=true
  fi

fi

# --- docs-drift (SEMANTIC) ---
# When devshop tooling changes, ALWAYS require a review explanation.
# The explanation is adversarially reviewed — no auto-pass.
RUN_DRIFT_CHECK=false
if [ "$CURRENT_REPO" = "devshop" ]; then
  RUN_DRIFT_CHECK=true
elif [ "$CURRENT_REPO" = "project" ] && [ ${#DEVSHOP_FILES[@]} -gt 0 ]; then
  RUN_DRIFT_CHECK=true
fi

if [ "$RUN_DRIFT_CHECK" = true ]; then
  # Skip changelog-only / version-only commits
  if [ "$CURRENT_REPO" = "devshop" ]; then
    # In the devshop repo, all files under kit/ are devshop tooling
    NON_CHANGELOG=$(echo "$STAGED" | grep -E '^kit/' | grep -vE '^kit/(docs/CHANGELOG\.md|version)$' || true)
  else
    # In project repos, devshop files are under .devshopkit/, .claude/, or .dcg.toml
    NON_CHANGELOG=$(echo "$STAGED" | grep -E "$DEVSHOP_REGEX" | grep -vE '^\.devshopkit/(docs/CHANGELOG\.md|version)$' || true)
  fi

  if [ -n "$NON_CHANGELOG" ]; then
    REVIEW_NOTES=$(git config --get devshop.docsVerified 2>/dev/null || true)

    if [ -n "$REVIEW_NOTES" ]; then
      # Review notes provided — run adversarial review
      echo "⏳ Docs drift: reviewing notes with adversarial agent..."
      REVIEW_RESULT=$(bash "$SCRIPT_DIR/adversarial-review.sh" docsVerified "$REVIEW_NOTES" 2>&1) || {
        echo ""
        echo "✖ ADVERSARIAL REVIEW REJECTED your docs review notes."
        echo "  $REVIEW_RESULT"
        echo ""
        echo "  Address the finding above, then update your review notes and retry."
        FAILED=true
      }
      if [ "$FAILED" = false ]; then
        echo "✓ Docs drift: adversarial review accepted."
      fi
    else
      echo ""
      echo "✖ BLOCKING: Devshop tooling changed — docs review required."
      echo ""
      echo "  Changed devshop files:"
      echo "$NON_CHANGELOG" | sed 's/^/    /'
      echo ""
      echo "  Review ALL of these docs — even if they don't mention the changed code yet"
      echo "  (new functionality needs to be documented for the first time):"
      echo "    kit/docs/MODEL.md      — conceptual model"
      echo "    kit/docs/OVERVIEW.md   — devshop overview"
      echo "    kit/docs/guide/        — operational reference (workflow, conventions, hooks, security, architecture, ops)"
      echo "    CLAUDE.md               — devshop conventions (repo root)"
      echo "    kit/docs/FAQ.md        — design rationale"
      echo "    CLAUDE.md (project)    — project-specific conventions"
      echo "    README.md              — user-facing description and commands"
      echo ""
      echo "  1. Read each doc above"
      echo "  2. Check if the committed changes introduce, modify, or remove"
      echo "     something that should be reflected — including new additions"
      echo "  3. Stage any doc updates"
      echo "  4. Retry with your review notes:"
      echo "     git -c devshop.docsVerified=\"<which docs you checked and what you updated or why no update needed>\" commit ..."
      echo ""
      echo "  Your notes will be verified by an independent reviewer."
      FAILED=true
    fi
  fi
fi

# --- doc-consistency (SEMANTIC) ---
# When any devshop reference doc is staged, ALWAYS require a review explanation.
# Adversarially reviewed — no auto-pass even when all docs are staged.
HAS_CLAUDE_MD=false
HAS_MODEL=false
HAS_OVERVIEW=false
HAS_GUIDE=false
HAS_FAQ=false
# In the devshop repo, CLAUDE.md is at the root. In project repos, CLAUDE.md is a project file — skip it.
[ "$CURRENT_REPO" = "devshop" ] && echo "$STAGED" | grep -q '^CLAUDE\.md$' && HAS_CLAUDE_MD=true
echo "$STAGED" | grep -q '^kit/docs/MODEL\.md$' && HAS_MODEL=true
echo "$STAGED" | grep -q '^kit/docs/OVERVIEW\.md$' && HAS_OVERVIEW=true
echo "$STAGED" | grep -qE '^kit/docs/guide/' && HAS_GUIDE=true
echo "$STAGED" | grep -q '^kit/docs/FAQ\.md$' && HAS_FAQ=true

DOC_COUNT=0
CHANGED_DOCS=()
UNCHANGED_DOCS=()
$HAS_CLAUDE_MD && DOC_COUNT=$((DOC_COUNT + 1)) && CHANGED_DOCS+=("CLAUDE.md") || UNCHANGED_DOCS+=("CLAUDE.md  (devshop conventions)")
$HAS_MODEL && DOC_COUNT=$((DOC_COUNT + 1)) && CHANGED_DOCS+=("MODEL.md") || UNCHANGED_DOCS+=("kit/docs/MODEL.md  (conceptual model)")
$HAS_OVERVIEW && DOC_COUNT=$((DOC_COUNT + 1)) && CHANGED_DOCS+=("OVERVIEW.md") || UNCHANGED_DOCS+=("kit/docs/OVERVIEW.md  (orientation)")
# guide/ is a directory of focused docs (workflow, conventions, hooks, security, architecture, ops).
# Any change to a file inside triggers the consistency check for the whole doc set.
$HAS_GUIDE && DOC_COUNT=$((DOC_COUNT + 1)) && CHANGED_DOCS+=("guide/") || UNCHANGED_DOCS+=("kit/docs/guide/  (operational reference — 7 files)")
$HAS_FAQ && DOC_COUNT=$((DOC_COUNT + 1)) && CHANGED_DOCS+=("FAQ.md") || UNCHANGED_DOCS+=("kit/docs/FAQ.md  (design rationale)")

if [ "$DOC_COUNT" -gt 0 ]; then
  CHANGED_LIST=$(IFS=', '; echo "${CHANGED_DOCS[*]}")
  REVIEW_NOTES=$(git config --get devshop.docSyncReason 2>/dev/null || true)

  if [ -n "$REVIEW_NOTES" ]; then
    # Review notes provided — run adversarial review
    echo "⏳ Doc consistency: reviewing notes with adversarial agent..."
    REVIEW_RESULT=$(bash "$SCRIPT_DIR/adversarial-review.sh" docSyncReason "$REVIEW_NOTES" 2>&1) || {
      echo ""
      echo "✖ ADVERSARIAL REVIEW REJECTED your doc consistency notes."
      echo "  $REVIEW_RESULT"
      echo ""
      echo "  Address the finding above, then update your review notes and retry."
      FAILED=true
    }
    if [ "$FAILED" = false ]; then
      echo "✓ Doc consistency: adversarial review accepted."
    fi
  else
    echo ""
    echo "✖ BLOCKING: Reference doc changed ($CHANGED_LIST) — review required."
    echo ""
    if [ ${#UNCHANGED_DOCS[@]} -gt 0 ]; then
      echo "  Other docs to check for consistency:"
      for doc in "${UNCHANGED_DOCS[@]}"; do echo "    $doc"; done
      echo ""
    fi
    echo "  1. Read each doc listed above"
    echo "  2. Update anything inconsistent with your changes"
    echo "  3. Stage any doc changes"
    echo "  4. Retry with your review notes:"
    echo "     git -c devshop.docSyncReason=\"<what you checked and changed>\" commit ..."
    echo ""
    echo "  Your notes will be verified by an independent reviewer."
    FAILED=true
  fi
fi

# --- cross-repo (DETERMINISTIC) ---
# Auto-passes when the other repo is clean. Bypass reason adversarially reviewed.
if [ -n "$OTHER_REPO" ] && [ -d "$OTHER_REPO/.git" ]; then
  OTHER_DIRTY=$(git -C "$OTHER_REPO" status --porcelain 2>/dev/null | head -10 || true)

  if [ -n "$OTHER_DIRTY" ]; then
    BYPASS_REASON=$(git config --get devshop.crossRepoReason 2>/dev/null || true)

    if [ -n "$BYPASS_REASON" ]; then
      # Reason provided — run adversarial review
      echo "⏳ Cross-repo: reviewing reason with adversarial agent..."
      REVIEW_RESULT=$(bash "$SCRIPT_DIR/adversarial-review.sh" crossRepoReason "$BYPASS_REASON" "$OTHER_DIRTY" 2>&1) || {
        echo ""
        echo "✖ ADVERSARIAL REVIEW REJECTED your cross-repo reason."
        echo "  $REVIEW_RESULT"
        echo ""
        echo "  Address the finding above, then update your reason and retry."
        FAILED=true
      }
      if [ "$FAILED" = false ]; then
        echo "✓ Cross-repo: adversarial review accepted."
      fi
    else
      echo ""
      echo "✖ The $OTHER_NAME repo has uncommitted changes:"
      echo "$OTHER_DIRTY" | sed 's/^/    /'
      echo ""
      echo "  Commit there first, or explain why with:"
      echo "    git -c devshop.crossRepoReason=\"<why it's OK>\" commit ..."
      echo ""
      echo "  Your reason will be verified by an independent reviewer."
      FAILED=true
    fi
  fi
fi

# --- release-coverage (SEMANTIC, devshop repo only) ---
# Fires when kit/version is staged (a release/version-bump commit). Reviews
# whether all changes since the last release tag have adequate test coverage.
# The adversarial review is PRIMARY (not a bypass review) — it judges coverage
# directly. On FAIL, the committer can add tests + retry, or bypass via
# `git -c devshop.releaseReviewed="<why>"` which re-runs the review with the
# justification included in context.
if [ "$CURRENT_REPO" = "devshop" ] && echo "$STAGED" | grep -q '^kit/version$'; then
  OLD_VERSION=$(git show HEAD:kit/version 2>/dev/null | tr -d '[:space:]' || true)
  if [ -n "$OLD_VERSION" ]; then
    LAST_TAG="v$OLD_VERSION"
    if git rev-parse "$LAST_TAG" &>/dev/null; then
      CHANGED_FILES=$(git diff --cached --name-only "$LAST_TAG" 2>/dev/null || true)
      TEST_CHANGES=$(echo "$CHANGED_FILES" | grep '^kit/tests/' || true)
      FULL_DIFF=$(git diff --cached "$LAST_TAG" 2>/dev/null | head -500 || true)

      TEST_SUMMARY=""
      for tf in kit/tests/*.bats; do
        [ -f "$tf" ] || continue
        TEST_SUMMARY+="--- $(basename "$tf") ---
$(grep '@test ' "$tf" | sed 's/.*@test "//;s/".*//')
"
      done

      BYPASS_REASON=$(git config --get devshop.releaseReviewed 2>/dev/null || true)

      REVIEW_CONTEXT="Release commit — reviewing coverage of all changes since $LAST_TAG.

Files changed since $LAST_TAG:
$CHANGED_FILES

Test files modified since $LAST_TAG:
${TEST_CHANGES:-(none)}

Full diff since last tag (first 500 lines):
$FULL_DIFF

Test suite coverage (test names per file):
$TEST_SUMMARY"

      if [ -n "$BYPASS_REASON" ]; then
        REVIEW_CONTEXT="$REVIEW_CONTEXT

Developer's justification for why any coverage gap is acceptable:
$BYPASS_REASON"
      fi

      echo "⏳ Release coverage: reviewing with adversarial agent..."
      REVIEW_RESULT=$(bash "$SCRIPT_DIR/adversarial-review.sh" testCoverage "$REVIEW_CONTEXT" 2>&1) || {
        echo ""
        echo "✖ Pre-release test coverage review FAILED."
        echo "  $REVIEW_RESULT"
        echo ""
        if [ -z "$BYPASS_REASON" ]; then
          echo "  Address the gap (add tests or update existing ones), or bypass with:"
          echo "    git -c devshop.releaseReviewed=\"<why current coverage is sufficient>\" commit ..."
        else
          echo "  Your justification was rejected. Address the finding above or refine the justification."
        fi
        FAILED=true
      }
      if [ "$FAILED" = false ]; then
        echo "✓ Release coverage: adversarial review accepted."
      fi
    fi
  fi
fi

if [ "$FAILED" = true ]; then
  exit 1
fi
